<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shipping | Kosher Market</title><style>body{font-family:system-ui,sans-serif;background:#f6f8fb;color:#111827;margin:0}.wrap{max-width:1100px;margin:30px auto;padding:20px}.card{background:#fff;padding:22px;border-radius:16px;margin-bottom:20px;box-shadow:0 6px 24px rgba(0,0,0,.06)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field{display:flex;flex-direction:column;gap:6px}.field.full{grid-column:1/-1}input,select,button{padding:11px;border:1px solid #d1d5db;border-radius:8px;font:inherit}button{background:#111827;color:#fff;cursor:pointer}.countries{height:180px}.zone{border:1px solid #e5e7eb;padding:16px;border-radius:12px;margin-top:14px}.tag{display:inline-block;background:#eef2ff;border-radius:999px;padding:4px 8px;margin:3px;font-size:12px}</style></head><body><div class="wrap"><h1>Global Shipping</h1><p>Configure where you ship and your BTC shipping rates. Customer checkout will only show eligible methods.</p>@if(session('success'))<div class="card">{{ session('success') }}</div>@endif<div class="card"><h2>Create shipping zone</h2><form method="POST" action="{{ route('vendor.shipping.zones.store') }}">@csrf<div class="grid"><div class="field"><label>Zone name</label><input name="name" placeholder="Europe Standard" required></div><div class="field"><label>Countries</label><select class="countries" name="countries[]" multiple required>@foreach($countries as $country)<option value="{{ $country->id }}">{{ $country->name }} ({{ $country->code }})</option>@endforeach</select></div></div><button type="submit">Create zone</button></form></div><div class="card"><h2>Add shipping rate</h2><form method="POST" action="{{ route('vendor.shipping.rates.store') }}">@csrf<div class="grid"><div class="field"><label>Zone</label><select name="shipping_zone_id" required>@foreach($zones as $zone)<option value="{{ $zone->id }}">{{ $zone->name }}</option>@endforeach</select></div><div class="field"><label>Service name</label><input name="service_name" placeholder="International Standard" required></div><div class="field"><label>Price (BTC)</label><input name="price_btc" type="number" min="0" step="0.00000001" required></div><div class="field"><label>Free shipping threshold (BTC)</label><input name="free_shipping_threshold_btc" type="number" min="0" step="0.00000001"></div><div class="field"><label>Minimum delivery days</label><input name="min_delivery_days" type="number" min="0" max="365" required></div><div class="field"><label>Maximum delivery days</label><input name="max_delivery_days" type="number" min="0" max="365" required></div><div class="field full"><label>Tracking URL template (optional)</label><input name="tracking_url_template" type="url" placeholder="https://carrier.example/track"></div></div><button type="submit">Add rate</button></form></div><div class="card"><h2>Your shipping zones</h2>@forelse($zones as $zone)<div class="zone"><strong>{{ $zone->name }}</strong><div>@foreach($zone->countries as $country)<span class="tag">{{ $country->code }}</span>@endforeach</div><ul>@forelse($zone->rates as $rate)<li>{{ $rate->service_name }} — {{ number_format((float)$rate->price_btc,8) }} BTC — {{ $rate->min_delivery_days }}–{{ $rate->max_delivery_days }} days</li>@empty<li>No rates configured.</li>@endforelse</ul></div>@empty<p>No shipping zones configured yet.</p>@endforelse</div></div></body></html>
